hooks.extraMethods:
; Finalizar Volumes marcados no grid (coluna Check)
;
; set sc=$$FinalizarVolumesMarcados^WDOMTESTEROM110ATAB3RG(codEmpresa,codRomaneio,term,.qtdFinalizados)
FinalizarVolumesMarcados(codEmpresa,codRomaneio,term,qtdFinalizados)	;
$$$VAR
new sc,linha,mtemp,codVolume,tabVolume,erro
;
set (qtdFinalizados,erro)=0
kill tabVolume
set linha=""
for  set linha=$order(^mtempWDOMTESTEROM110ATAB3CHECK(term,31,1,linha)) quit:linha=""  do
. set mtemp=$get(^mtempWDOMTESTEROM110ATAB3(term,linha))
. if $piece(mtemp,Z,1)'="" set tabVolume($piece(mtemp,Z,1))=""
;
if '$data(tabVolume) quit $$$ERROR(10000,"Marque os volumes que deseja finalizar!")
;
set sc=$$$OK,codVolume=""
for  set codVolume=$order(tabVolume(codVolume)) quit:codVolume=""  do
. quit:$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume)),Z,4)="E"
. set sc=$$FinalizarVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
. if $$$ISOK(sc) set qtdFinalizados=qtdFinalizados+1
;
quit sc

ruleHooks.extraMethods:
; Obter Próximo Código do Romaneio (não reaproveita)
;
; set sc=$$ObterProximoRomaneio^WDOMTESTEROM110ARG(codEmpresa,.codRomaneio)
ObterProximoRomaneio(codEmpresa,codRomaneio)	;
$$$VAR
;
set codRomaneio=$increment(^WDOMTESTEROMC(2,codEmpresa,0))
;
quit $$$OK
;
; Obter Tabela de Romaneios (F7 de cadastrados)
;
; set sc=$$ObterTabRomaneio^WDOMTESTEROM110ARG(codEmpresa,.tabRomaneio)
ObterTabRomaneio(codEmpresa,tabRomaneio)	;
$$$VAR
new sc,codRomaneio,dados,codChecklist,dadosChecklist,ftcl
;
kill tabRomaneio
set codRomaneio=""
for  set codRomaneio=$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio)) quit:codRomaneio=""  do
. set dados=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1))
. set codChecklist=$piece(dados,Z,4),(dadosChecklist,ftcl)=""
. if codChecklist'="" set dadosChecklist=$get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1))
. if $piece(dadosChecklist,Z,5)'="" set sc=$$ObterNomeCliente^CCFT760RG(codEmpresa,$piece(dadosChecklist,Z,5),.ftcl)
. set tabRomaneio(codRomaneio)=codChecklist_Z_$piece(ftcl,Z,2)_Z_$select($$RomaneioFinalizado(codEmpresa,codRomaneio):"Finalizado",1:"Aberto")
;
quit $$$OK
;
; Obter Tabela de Checklists não encerrados (F7 do Checklist)
;
; set sc=$$ObterTabChecklistAberto^WDOMTESTEROM110ARG(codEmpresa,.tabChecklist)
ObterTabChecklistAberto(codEmpresa,tabChecklist)	;
$$$VAR
new sc,codChecklist,dados,ftcl
;
kill tabChecklist
set codChecklist=""
for  set codChecklist=$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist)) quit:codChecklist=""  do
. set dados=$get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1))
. quit:$piece(dados,Z,3)="E"
. set ftcl=""
. if $piece(dados,Z,5)'="" set sc=$$ObterNomeCliente^CCFT760RG(codEmpresa,$piece(dados,Z,5),.ftcl)
. set tabChecklist(codChecklist)=$piece(ftcl,Z,2)_Z_$extract($piece(dados,Z,6),1,60)
;
quit $$$OK
;
; Validar Checklist do Romaneio (existe, não encerrado e não trocado depois de salvo)
;
; set sc=$$ValidarChecklistRomaneio^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codChecklist)
ValidarChecklistRomaneio(codEmpresa,codRomaneio,codChecklist)	;
$$$VAR
new checklistAtual
;
if $get(codChecklist)="" quit $$$ERROR(10000,"Checklist: Campo obrigatório!")
if '$data(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1)) quit $$$ERROR(10000,"Checklist "_codChecklist_" não cadastrado!")
;
set checklistAtual=$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,+$get(codRomaneio),1)),Z,4)
if checklistAtual'="",checklistAtual'=codChecklist quit $$$ERROR(10000,"O romaneio já está vinculado ao checklist "_checklistAtual_" e não pode ser alterado!")
if checklistAtual="",$piece($get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1)),Z,3)="E" quit $$$ERROR(10000,"Checklist "_codChecklist_" está encerrado!")
;
quit $$$OK
;
; Obter Dados do Cliente do Checklist
; dadosCliente = cliente^endereço^bairro^cidade^uf^email^contato^telefone^observação do checklist^cep^número
;
; set sc=$$ObterDadosClienteChecklist^WDOMTESTEROM110ARG(codEmpresa,codChecklist,.dadosCliente)
ObterDadosClienteChecklist(codEmpresa,codChecklist,dadosCliente)	;
$$$VAR
new sc,dadosChecklist,codCliente,ftcl,ftcl2,csci
;
set dadosCliente=""
if $get(codChecklist)="" quit $$$OK
;
set dadosChecklist=$get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,1))
set codCliente=$piece(dadosChecklist,Z,5)
set $piece(dadosCliente,Z,1)=codCliente
set $piece(dadosCliente,Z,9)=$piece(dadosChecklist,Z,6)
if codCliente="" quit $$$OK
;
set (ftcl,ftcl2,csci)=""
set sc=$$VerCliente^CCFTRG001(codEmpresa,codCliente,.ftcl)
if $$$ISERR(sc) quit sc
set sc=$$ObterDadosCobrancaCliente^CCFTRG001(codEmpresa,codCliente,.ftcl2)
if $piece(ftcl,Z,6)'="" set sc=$$VerCidade^CCAPLRG001($piece(ftcl,Z,6),.csci)
;
set $piece(dadosCliente,Z,2)=$piece(ftcl,Z,3)
set $piece(dadosCliente,Z,3)=$piece(ftcl,Z,4)
set $piece(dadosCliente,Z,4)=$piece(csci,Z,1)
set $piece(dadosCliente,Z,5)=$piece(csci,Z,2)
set $piece(dadosCliente,Z,6)=$piece(ftcl,Z,33)
set $piece(dadosCliente,Z,7)=$piece(ftcl2,Z,6)
set $piece(dadosCliente,Z,8)=$piece(ftcl2,Z,2)
set $piece(dadosCliente,Z,10)=$piece(ftcl,Z,6)
set $piece(dadosCliente,Z,11)=$piece(ftcl,Z,52)
;
quit $$$OK
;
; Vincular Checklist ao Romaneio: grava o vínculo, copia os itens do checklist
; que não estão em outro romaneio e grava o histórico no checklist.
;
; set sc=$$VincularChecklistRomaneio^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codChecklist)
VincularChecklistRomaneio(codEmpresa,codRomaneio,codChecklist)	;
$$$VAR
new dataHora,codOperador,codSequencia,dados
;
if $get(codChecklist)="" quit $$$OK
if $data(^WDOMTESTEROMC(2,codEmpresa,2,codChecklist,1,codRomaneio)) quit $$$OK
;
set dataHora=$$$horologEmp(codEmpresa)
set codOperador=$$VEROP^%CSUTIUD(1)
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,2,codChecklist,1,codRomaneio),dataHora_Z_codOperador)
;
set codSequencia=""
for  set codSequencia=$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia)) quit:codSequencia=""  do
. quit:$$ItemEmOutroRomaneio(codEmpresa,codChecklist,codSequencia,codRomaneio)
. set dados=$get(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia))
. do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia),dataHora_Z_codOperador_Z_$piece(dados,Z,3,6))
;
do GravarHistoricoChecklist(codEmpresa,codChecklist,"Inclusão do checklist "_codChecklist_" no romaneio de carga "_codRomaneio)
;
quit $$$OK
;
; Item do checklist já está em outro romaneio?
;
; set emOutro=$$ItemEmOutroRomaneio^WDOMTESTEROM110ARG(codEmpresa,codChecklist,codSequencia,codRomaneio)
ItemEmOutroRomaneio(codEmpresa,codChecklist,codSequencia,codRomaneio)	;
$$$VAR
new outroRomaneio,achou
;
set (outroRomaneio,achou)=""
for  set outroRomaneio=$order(^WDOMTESTEROMC(2,codEmpresa,2,codChecklist,1,outroRomaneio)) quit:outroRomaneio=""!achou  do
. quit:outroRomaneio=codRomaneio
. if $data(^WDOMTESTEROMC(2,codEmpresa,1,outroRomaneio,2,codSequencia)) set achou=1
;
quit +achou
;
; Gravar Histórico no Checklist
;
; do GravarHistoricoChecklist^WDOMTESTEROM110ARG(codEmpresa,codChecklist,descricao)
GravarHistoricoChecklist(codEmpresa,codChecklist,descricao)	;
$$$VAR
new codSequenciaHistorico
;
quit:$get(codChecklist)=""
set codSequenciaHistorico=+$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,3,""),-1)+1
do $$$SetG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,3,codSequenciaHistorico),$$$horologEmp(codEmpresa)_Z_$$VEROP^%CSUTIUD(1)_Z_$translate(descricao,Z," "))
;
quit
;
; Romaneio finalizado? (data/hora de finalização no piece 16)
;
; set finalizado=$$RomaneioFinalizado^WDOMTESTEROM110ARG(codEmpresa,codRomaneio)
RomaneioFinalizado(codEmpresa,codRomaneio)	;
$$$VAR
;
quit $piece($get(^WDOMTESTEROMC(2,codEmpresa,1,+$get(codRomaneio),1)),Z,16)'=""
;
; Validar Romaneio em aberto (para alterar itens e volumes)
;
; set sc=$$ValidarRomaneioAberto^WDOMTESTEROM110ARG(codEmpresa,codRomaneio)
ValidarRomaneioAberto(codEmpresa,codRomaneio)	;
$$$VAR
;
if $get(codRomaneio)="" quit $$$ERROR(10000,"Romaneio: Campo obrigatório!")
if '$data(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1)) quit $$$ERROR(10000,"Salve o romaneio na aba Dados Gerais!")
if $$RomaneioFinalizado(codEmpresa,codRomaneio) quit $$$ERROR(10000,"Romaneio "_codRomaneio_" está finalizado!")
;
quit $$$OK
;
; Finalizar Romaneio (Conclusão): grava os dados de entrega/transporte e finaliza
;
; set sc=$$FinalizarRomaneio^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,dados)
FinalizarRomaneio(codEmpresa,codRomaneio,dados)	;
$$$VAR
new sc,atual,piece
;
set sc=$$ValidarRomaneioAberto(codEmpresa,codRomaneio)
if $$$ISERR(sc) quit sc
;
set atual=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1))
for piece=6:1:15 set $piece(atual,Z,piece)=$translate($piece($get(dados),Z,piece),Z," ")
;
if $piece(atual,Z,11)="" quit $$$ERROR(10000,"Endereço: Campo obrigatório!")
if $piece(atual,Z,12)="" quit $$$ERROR(10000,"Transportadora: Campo obrigatório!")
if $piece(atual,Z,13)="" quit $$$ERROR(10000,"Motorista: Campo obrigatório!")
if $piece(atual,Z,14)="" quit $$$ERROR(10000,"Placa Caminhão: Campo obrigatório!")
;
set $piece(atual,Z,16)=$$$horologEmp(codEmpresa)
set $piece(atual,Z,17)=$$VEROP^%CSUTIUD(1)
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1),atual)
;
quit $$$OK
;
; Obter Tabela de Placas já usadas (F7 da Placa)
;
; set sc=$$ObterTabPlaca^WDOMTESTEROM110ARG(codEmpresa,.tabPlaca)
ObterTabPlaca(codEmpresa,tabPlaca)	;
$$$VAR
new codRomaneio,dados,placa
;
kill tabPlaca
set codRomaneio=""
for  set codRomaneio=$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio)) quit:codRomaneio=""  do
. set dados=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1))
. set placa=$piece(dados,Z,14)
. if placa'="" set tabPlaca(placa)=$piece(dados,Z,13)
;
quit $$$OK
;
; Excluir Romaneio: exclui volumes, itens e os vínculos com o checklist (com histórico)
;
; set sc=$$ExcluirRomaneio^WDOMTESTEROM110ARG(codEmpresa,codRomaneio)
ExcluirRomaneio(codEmpresa,codRomaneio)	;
$$$VAR
new codChecklist,codSequencia,codProduto
;
if $get(codRomaneio)="" quit $$$ERROR(10000,"Selecione um romaneio!")
if '$data(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio)) quit $$$ERROR(10000,"Romaneio "_codRomaneio_" não cadastrado!")
if $$RomaneioFinalizado(codEmpresa,codRomaneio) quit $$$ERROR(10000,"Romaneio "_codRomaneio_" está finalizado e não pode ser excluído!")
;
set codSequencia=""
for  set codSequencia=$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia)) quit:codSequencia=""  do
. set codProduto=$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia)),Z,5)
. if codProduto'="" do $$$KillG(^WDOMTESTEROMC(2,codEmpresa,3,codProduto,codRomaneio,codSequencia))
;
set codChecklist=$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1)),Z,4)
if codChecklist'="" do
. do $$$KillG(^WDOMTESTEROMC(2,codEmpresa,2,codChecklist,1,codRomaneio))
. do GravarHistoricoChecklist(codEmpresa,codChecklist,"Exclusão do vínculo do checklist "_codChecklist_" com o romaneio de carga "_codRomaneio)
;
do $$$KillG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio))
;
quit $$$OK
;
; ---------------------------------------------------------------- Engenharia e Volumes
;
; Item do romaneio já está em algum volume?
;
; set volume=$$VolumeDoItem^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codSequencia)
VolumeDoItem(codEmpresa,codRomaneio,codSequencia)	;
$$$VAR
new codProduto
;
set codProduto=$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia)),Z,5)
if codProduto="" quit ""
;
quit $order(^WDOMTESTEROMC(2,codEmpresa,3,codProduto,codRomaneio,codSequencia,""))
;
; Obter Próximo Volume do Romaneio (não reaproveita)
;
; set sc=$$ObterProximoVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,.codVolume)
ObterProximoVolume(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
;
set codVolume=$increment(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3))
;
quit $$$OK
;
; Obter Tabela de Volumes do Romaneio (F7 da Etiqueta Volume)
;
; set sc=$$ObterTabVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,.tabVolume)
ObterTabVolume(codEmpresa,codRomaneio,tabVolume)	;
$$$VAR
new sc,codVolume,dados,embalagem
;
kill tabVolume
if $get(codRomaneio)="" quit $$$OK
set codVolume=""
for  set codVolume=$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume)) quit:codVolume=""  do
. set dados=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume)),embalagem=""
. if $piece(dados,Z,3)'="" set sc=$$VerEmbalagem^WDOMTESTEROM005RG(codEmpresa,$piece(dados,Z,3),.embalagem)
. set tabVolume(codVolume)=$piece(embalagem,Z,1)_Z_$select($piece(dados,Z,4)="E":"Encerrado",1:"Em Aberto")
;
quit $$$OK
;
; Obter Volume (dataHora^op^embalagem^situação^...)
;
; set sc=$$ObterVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume,.dadosVolume)
ObterVolume(codEmpresa,codRomaneio,codVolume,dadosVolume)	;
$$$VAR
;
set dadosVolume=""
if '$data(^WDOMTESTEROMC(2,codEmpresa,1,+$get(codRomaneio),3,+$get(codVolume))) quit $$$ERROR(10000,"Volume "_$get(codVolume)_" não cadastrado!")
set dadosVolume=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume))
;
quit $$$OK
;
; Gravar Volume (Confirmar): cria o volume em aberto ou troca a embalagem
;
; set sc=$$GravarVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume,codEmbalagem)
GravarVolume(codEmpresa,codRomaneio,codVolume,codEmbalagem)	;
$$$VAR
new sc,dados,embalagem,dataHora,codOperador
;
set sc=$$ValidarRomaneioAberto(codEmpresa,codRomaneio)
if $$$ISERR(sc) quit sc
if $get(codVolume)="" quit $$$ERROR(10000,"Etiqueta Volume: Campo obrigatório!")
set sc=$$VerEmbalagem^WDOMTESTEROM005RG(codEmpresa,$get(codEmbalagem),.embalagem)
if $$$ISERR(sc) quit sc
;
set dataHora=$$$horologEmp(codEmpresa)
set codOperador=$$VEROP^%CSUTIUD(1)
set dados=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume))
if $piece(dados,Z,4)="E" quit $$$ERROR(10000,"Volume "_codVolume_" está encerrado!")
if dados="" set $piece(dados,Z,4)="A",$piece(dados,Z,5)=+$horolog,$piece(dados,Z,6)=codOperador
;
set $piece(dados,Z,1)=dataHora
set $piece(dados,Z,2)=codOperador
set $piece(dados,Z,3)=codEmbalagem
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume),dados)
;
quit $$$OK
;
; Validar Volume em aberto (para inserir/remover itens)
;
; set sc=$$ValidarVolumeAberto^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
ValidarVolumeAberto(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
new sc,dados
;
set sc=$$ValidarRomaneioAberto(codEmpresa,codRomaneio)
if $$$ISERR(sc) quit sc
set sc=$$ObterVolume(codEmpresa,codRomaneio,$get(codVolume),.dados)
if $$$ISERR(sc) quit $$$ERROR(10000,"Informe o volume e clique em Confirmar!")
if $piece(dados,Z,4)="E" quit $$$ERROR(10000,"Volume "_codVolume_" está encerrado!")
;
quit $$$OK
;
; Inserir Item do Romaneio no Volume
;
; set sc=$$InserirItemVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume,codSequencia)
InserirItemVolume(codEmpresa,codRomaneio,codVolume,codSequencia)	;
$$$VAR
new sc,dados,codProduto,dataHora,codOperador,volumeAtual
;
set sc=$$ValidarVolumeAberto(codEmpresa,codRomaneio,$get(codVolume))
if $$$ISERR(sc) quit sc
if $get(codSequencia)="" quit $$$ERROR(10000,"Selecione um item do checklist!")
if '$data(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia)) quit $$$ERROR(10000,"Item "_codSequencia_" não está no romaneio!")
;
set volumeAtual=$$VolumeDoItem(codEmpresa,codRomaneio,codSequencia)
if volumeAtual'="" quit $$$ERROR(10000,"Item "_codSequencia_" já está no volume "_volumeAtual_"!")
;
set dados=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia))
set codProduto=$piece(dados,Z,5)
set dataHora=$$$horologEmp(codEmpresa)
set codOperador=$$VEROP^%CSUTIUD(1)
;
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume,codSequencia),dataHora_Z_codOperador_Z_$piece(dados,Z,3,6))
if codProduto'="" do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,3,codProduto,codRomaneio,codSequencia,codVolume),dataHora_Z_codOperador)
;
quit $$$OK
;
; Inserir Produto no Volume pelo código de barras (GTIN) ou código do produto:
; usa o primeiro item pendente do romaneio com esse produto.
;
; set sc=$$InserirProdutoVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume,codigo)
InserirProdutoVolume(codEmpresa,codRomaneio,codVolume,codigo)	;
$$$VAR
new sc,codProduto,codSequencia,achou
;
if $get(codigo)="" quit $$$ERROR(10000,"Informe o código de barras ou o produto!")
set sc=$$ValidarVolumeAberto(codEmpresa,codRomaneio,$get(codVolume))
if $$$ISERR(sc) quit sc
;
set codProduto=""
set sc=$$ObterItemLeituraGTIN^CCPGQ040ARG(codEmpresa,codigo,.codProduto)
if $$$ISERR(sc)!(codProduto="") set codProduto=codigo
;
set (codSequencia,achou)=""
for  set codSequencia=$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia)) quit:codSequencia=""!(achou'="")  do
. quit:$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia)),Z,5)'=codProduto
. if $$VolumeDoItem(codEmpresa,codRomaneio,codSequencia)="" set achou=codSequencia
;
if achou="" quit $$$ERROR(10000,"Produto "_codProduto_" não está pendente nos itens do checklist!")
;
quit $$InserirItemVolume(codEmpresa,codRomaneio,codVolume,achou)
;
; Remover Item do Volume (volta para os itens pendentes)
;
; set sc=$$RemoverItemVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume,codSequencia)
RemoverItemVolume(codEmpresa,codRomaneio,codVolume,codSequencia)	;
$$$VAR
new sc,codProduto
;
set sc=$$ValidarVolumeAberto(codEmpresa,codRomaneio,$get(codVolume))
if $$$ISERR(sc) quit sc
if $get(codSequencia)=""!'$data(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume,+$get(codSequencia))) quit $$$ERROR(10000,"Selecione um item do volume!")
;
set codProduto=$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume,codSequencia)),Z,5)
do $$$KillG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume,codSequencia))
if codProduto'="" do $$$KillG(^WDOMTESTEROMC(2,codEmpresa,3,codProduto,codRomaneio,codSequencia,codVolume))
;
quit $$$OK
;
; Excluir Item do Romaneio (item pendente, fora de volume)
;
; set sc=$$ExcluirItemRomaneio^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codSequencia)
ExcluirItemRomaneio(codEmpresa,codRomaneio,codSequencia)	;
$$$VAR
new sc,volume
;
set sc=$$ValidarRomaneioAberto(codEmpresa,codRomaneio)
if $$$ISERR(sc) quit sc
if $get(codSequencia)=""!'$data(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,+$get(codSequencia))) quit $$$ERROR(10000,"Selecione um item do checklist!")
set volume=$$VolumeDoItem(codEmpresa,codRomaneio,codSequencia)
if volume'="" quit $$$ERROR(10000,"Item "_codSequencia_" está no volume "_volume_". Remova o item do volume antes!")
;
do $$$KillG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia))
do GravarHistoricoChecklist(codEmpresa,$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1)),Z,4),"Exclusão do item "_codSequencia_" do romaneio de carga "_codRomaneio)
;
quit $$$OK
;
; Incluir Novos Itens no Checklist do Romaneio (uma linha por unidade, como no checklist)
;
; set sc=$$IncluirNovoItemRomaneio^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codProduto,quantidade)
IncluirNovoItemRomaneio(codEmpresa,codRomaneio,codProduto,quantidade)	;
$$$VAR
new sc,codChecklist,codSequencia,contador,dados,cgigen
;
set sc=$$ValidarRomaneioAberto(codEmpresa,codRomaneio)
if $$$ISERR(sc) quit sc
set codChecklist=$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1)),Z,4)
if codChecklist="" quit $$$ERROR(10000,"Informe o checklist na aba Dados Gerais!")
if $get(codProduto)="" quit $$$ERROR(10000,"Produto: Campo obrigatório!")
set sc=$$VerItemCGIGEN^CCCGIRG001(codEmpresa,codProduto,.cgigen)
if $$$ISERR(sc) quit sc
if +$get(quantidade)<1 quit $$$ERROR(10000,"Quantidade: Campo obrigatório!")
;
set codSequencia=+$order(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,""),-1)
for contador=1:1:quantidade do
. set codSequencia=codSequencia+1
. set dados=$$$horologEmp(codEmpresa)_Z_$$VEROP^%CSUTIUD(1)_Z_""_Z_""_Z_codProduto_Z_1
. do $$$SetG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,2,codSequencia),dados)
. do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,2,codSequencia),dados)
;
do GravarHistoricoChecklist(codEmpresa,codChecklist,"Inclusão de "_quantidade_" item(ns) do produto "_codProduto_" pelo romaneio de carga "_codRomaneio)
;
quit $$$OK
;
; Finalizar Volume
;
; set sc=$$FinalizarVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
FinalizarVolume(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
new sc,dados
;
set sc=$$ValidarVolumeAberto(codEmpresa,codRomaneio,$get(codVolume))
if $$$ISERR(sc) quit sc
if $order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume,""))="" quit $$$ERROR(10000,"Volume "_codVolume_" sem itens!")
;
set dados=$get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume))
set $piece(dados,Z,4)="E"
set $piece(dados,Z,7)=$$$horologEmp(codEmpresa)
set $piece(dados,Z,8)=$$VEROP^%CSUTIUD(1)
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume),dados)
;
quit $$$OK
;
; Reabrir Volume
;
; set sc=$$ReabrirVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
ReabrirVolume(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
new sc,dados
;
set sc=$$ValidarRomaneioAberto(codEmpresa,codRomaneio)
if $$$ISERR(sc) quit sc
set sc=$$ObterVolume(codEmpresa,codRomaneio,$get(codVolume),.dados)
if $$$ISERR(sc) quit sc
if $piece(dados,Z,4)'="E" quit $$$ERROR(10000,"Volume "_codVolume_" já está em aberto!")
;
set $piece(dados,Z,4)="A"
set $piece(dados,Z,7)=""
set $piece(dados,Z,8)=""
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume),dados)
;
quit $$$OK
;
; Obter Medidas do Volume: pesoNeto^pesoBruto^altura^largura^profundidade^m3 (texto formatado)
; Os valores da embalagem estão gravados x1000 (3 decimais).
;
; set medidas=$$ObterMedidasVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
ObterMedidasVolume(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
new sc,embalagem,peso,altura,largura,profundidade
;
set embalagem=""
set sc=$$VerEmbalagem^WDOMTESTEROM005RG(codEmpresa,$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,+$get(codRomaneio),3,+$get(codVolume))),Z,3),.embalagem)
set peso=$piece(embalagem,Z,2)/1000
set altura=$piece(embalagem,Z,3)/1000
set largura=$piece(embalagem,Z,4)/1000
set profundidade=$piece(embalagem,Z,5)/1000
;
quit $fnumber(peso,".",3)_Z_$fnumber(peso,".",3)_Z_$fnumber(altura,".",3)_Z_$fnumber(largura,".",3)_Z_$fnumber(profundidade,".",3)_Z_$fnumber(altura*largura*profundidade,".",3)
;
; Documento de referência dos anexos do volume (componente %CSWANEXO)
;
; set docRef=$$DocRefAnexoVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
DocRefAnexoVolume(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
;
quit "Anexo - "_codEmpresa_" - Romaneio - "_codRomaneio_" - Volume - "_codVolume_" - WDOMTESTEROM110ARG"
;
; Registrar Anexos do Volume depois do %CSWANEXO (grava o docRef uma vez)
;
; set sc=$$RegistrarAnexoVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
RegistrarAnexoVolume(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
new sc,docRef,tabAnexos,codSequencia,achou
;
set docRef=$$DocRefAnexoVolume(codEmpresa,codRomaneio,codVolume)
set sc=$$ObterDadosAnexos^%CSWANEXORG(docRef,.tabAnexos)
if $$$ISERR(sc) quit $$$OK
;
set (codSequencia,achou)=""
for  set codSequencia=$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,4,codSequencia)) quit:codSequencia=""!achou  do
. if $piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,4,codSequencia)),Z,3)=docRef set achou=1
if achou quit $$$OK
;
set codSequencia=+$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,4,""),-1)+1
do $$$SetG(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,4,codSequencia),$$$horologEmp(codEmpresa)_Z_$$VEROP^%CSUTIUD(1)_Z_docRef)
;
quit $$$OK
;
; Imprimir Etiqueta do Volume (tela de etiquetas da Consistem, %CSW1TAG115)
; O tipo "EtiquetaVolumeRomaneio" precisa ser registrado no LOGCONF do módulo
; ($$$CriarEtiqueta) e o layout definido com o cliente.
;
; set sc=$$ImprimirEtiquetaVolume^WDOMTESTEROM110ARG(codEmpresa,codRomaneio,codVolume)
ImprimirEtiquetaVolume(codEmpresa,codRomaneio,codVolume)	;
$$$VAR
new sc,utiliza,tabVariaveis,dadosVolume,embalagem,medidas,dadosCliente,quantidade,codSequencia
;
set sc=$$ObterVolume(codEmpresa,codRomaneio,$get(codVolume),.dadosVolume)
if $$$ISERR(sc) quit sc
set sc=$$UtilizaConfiguracaoEtiqueta^%CSW1TAG("EtiquetaVolumeRomaneio",.utiliza)
if $$$ISERR(sc) quit sc
;
set embalagem=""
set sc=$$VerEmbalagem^WDOMTESTEROM005RG(codEmpresa,$piece(dadosVolume,Z,3),.embalagem)
set medidas=$$ObterMedidasVolume(codEmpresa,codRomaneio,codVolume)
set sc=$$ObterDadosClienteChecklist(codEmpresa,$piece($get(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,1)),Z,4),.dadosCliente)
set (codSequencia,quantidade)=""
for  set codSequencia=$order(^WDOMTESTEROMC(2,codEmpresa,1,codRomaneio,3,codVolume,codSequencia)) quit:codSequencia=""  set quantidade=quantidade+$piece(^(codSequencia),Z,6)
;
kill tabVariaveis
set tabVariaveis("codrom")=codRomaneio
set tabVariaveis("codvol")=codVolume
set tabVariaveis("codemb")=$piece(dadosVolume,Z,3)
set tabVariaveis("descemb")=$piece(embalagem,Z,1)
set tabVariaveis("peso")=$piece(medidas,Z,1)
set tabVariaveis("qtdpecas")=+quantidade
set tabVariaveis("codcli")=$piece(dadosCliente,Z,1)
;
quit $$PrintTag^%CSW1TAG("EtiquetaVolumeRomaneio",.tabVariaveis)
